"""Standalone HTML monitor for Xerrameca Dialogue Protocol v1."""

from __future__ import annotations


_HTML = r'''<!doctype html>
<html lang="ca"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pluribus · Xerrameca Monitor</title>
<style>
:root{color-scheme:dark;--bg:#0f172a;--panel:#172033;--panel2:#111827;--line:#334155;--text:#e2e8f0;--muted:#94a3b8;--accent:#38bdf8;--ok:#86efac;--warn:#fbbf24;--bad:#fca5a5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif}.wrap{max-width:1500px;margin:auto;padding:18px}.top,.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between}.title{font-size:1.65rem;font-weight:800;color:var(--accent)}.sub,.muted{color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:13px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px;margin-top:12px}.btn{border:1px solid var(--line);background:#1e293b;color:var(--text);padding:8px 10px;border-radius:7px;cursor:pointer;text-decoration:none}.btn:hover{border-color:#64748b}.primary{border-color:#0ea5e9;color:#7dd3fc}.warn{border-color:#f59e0b;color:var(--warn)}.bad{border-color:#ef4444;color:var(--bad)}input{background:#0b1220;border:1px solid var(--line);color:var(--text);border-radius:7px;padding:8px}.badge{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:2px 8px;font-size:.74rem}.ok{color:var(--ok);border-color:#22c55e}.warning{color:var(--warn);border-color:#f59e0b}.critical{color:var(--bad);border-color:#ef4444}.info{color:#7dd3fc;border-color:#0ea5e9}.kv{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:7px;margin-top:8px}.kv div{color:var(--muted);font-size:.78rem}.kv b{display:block;color:var(--text);font-size:.9rem;margin-top:2px}.list{display:grid;gap:9px;margin-top:10px}.item{background:var(--panel2);border:1px solid var(--line);border-radius:9px;padding:11px}.item-head{display:flex;justify-content:space-between;gap:8px;align-items:flex-start;flex-wrap:wrap}.name{font-weight:750}.small{font-size:.77rem}.hidden{display:none!important}.section{margin-top:18px}.section h2{font-size:1rem;color:#cbd5e1}.alert-critical{border-left:4px solid #ef4444}.alert-warning{border-left:4px solid #f59e0b}.alert-info{border-left:4px solid #0ea5e9}.toast{position:fixed;right:15px;bottom:15px;background:#111827;border:1px solid var(--line);padding:10px;border-radius:8px;max-width:420px}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}@media(max-width:650px){.wrap{padding:10px}}
</style></head><body><div class="wrap">
<div class="top"><div><div class="title">Xerrameca Monitor</div><div class="sub">Dialogue Protocol v1 · health, leases, loops i alertes</div></div><div class="row"><input id="key" type="password" placeholder="API key admin"><button class="btn primary" onclick="connect()">Connecta</button><a class="btn" href="/dashboard?view=xerrameca">Xerrameca</a><a class="btn" href="/dashboard">Dashboard</a></div></div>
<div id="locked" class="panel" style="margin-top:12px"><b>Introdueix una API key admin.</b> El monitor no carrega dades sense autenticació.</div>
<div id="app" class="hidden">
<div class="grid">
<div class="panel"><div class="item-head"><b>Monitor</b><span id="enabledBadge" class="badge">—</span></div><div class="row" style="margin-top:8px"><button class="btn" onclick="toggleMonitor()">Activa/Desactiva</button><button class="btn warn" onclick="tick()">Tick ara</button></div></div>
<div class="panel"><b>Health</b><div class="kv"><div>OK<b id="okCount">0</b></div><div>Warning<b id="warnCount">0</b></div><div>Critical<b id="critCount">0</b></div><div>Alertes obertes<b id="alertCount">0</b></div></div></div>
<div class="panel"><b>Refresh</b><div class="kv"><div>Auto<b>5 s</b></div><div>Últim tick<b id="checkedAt">—</b></div></div><button class="btn" style="margin-top:8px" onclick="refreshAll()">Actualitza</button></div>
</div>
<div class="section"><h2>Configuració</h2><div class="panel"><div class="row"><label>Poll <input id="poll" type="number" min="2" max="3600" step="1"></label><label>Stalled <input id="stalled" type="number" min="30" max="86400"></label><label>Near rounds <input id="near" type="number" min="1" max="20"></label><label>Loop window <input id="loop" type="number" min="3" max="12"></label><label><input id="pauseStalled" type="checkbox"> auto-pause stalled</label><label><input id="pauseLoop" type="checkbox"> auto-pause loop</label><button class="btn primary" onclick="saveSettings()">Desa</button></div><div class="small muted" style="margin-top:8px">Les auto-accions estan desactivades per defecte. El monitor només pot pausar; mai respon ni finalitza una conversa.</div></div></div>
<div class="section"><h2>Converses monitoritzades</h2><div id="conversations" class="list"></div></div>
<div class="section"><h2>Alertes persistents</h2><div id="alerts" class="list"></div></div>
</div></div><div id="toast" class="toast hidden"></div>
<script>
let key=sessionStorage.getItem('pluribus_admin_key')||'';let state={system:null,snapshot:null,alerts:[]};document.getElementById('key').value=key;const $=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(m){const t=$('toast');t.textContent=m;t.classList.remove('hidden');setTimeout(()=>t.classList.add('hidden'),3000)}async function api(path,opt={}){if(!key)throw Error('Falta API key');const h=Object.assign({'X-API-Key':key},opt.headers||{});if(opt.body)h['Content-Type']='application/json';const r=await fetch(path,Object.assign({},opt,{headers:h}));const txt=await r.text();let d=txt;try{d=txt?JSON.parse(txt):null}catch{}if(!r.ok)throw Error(d?.detail||d||`HTTP ${r.status}`);return d}async function connect(){key=$('key').value.trim();if(!key)return;sessionStorage.setItem('pluribus_admin_key',key);try{await refreshAll();$('locked').classList.add('hidden');$('app').classList.remove('hidden')}catch(e){toast(e.message)}}async function refreshAll(){const [system,snapshot,alerts]=await Promise.all([api('/v1/xerrameca/monitor/system'),api('/v1/xerrameca/monitor/snapshot'),api('/v1/xerrameca/monitor/alerts?limit=200')]);state={system,snapshot,alerts};render()}function render(){const s=state.system;$('enabledBadge').textContent=s.enabled?'ACTIU':'ATURAT';$('enabledBadge').className='badge '+(s.enabled?'ok':'warning');$('poll').value=s.poll_interval_seconds;$('stalled').value=s.stalled_after_seconds;$('near').value=s.near_rounds_threshold;$('loop').value=s.loop_window;$('pauseStalled').checked=s.auto_pause_stalled;$('pauseLoop').checked=s.auto_pause_loop;const cs=state.snapshot.conversations||[];$('okCount').textContent=cs.filter(x=>x.health==='ok').length;$('warnCount').textContent=cs.filter(x=>x.health==='warning').length;$('critCount').textContent=cs.filter(x=>x.health==='critical').length;$('alertCount').textContent=state.alerts.filter(x=>x.status!=='resolved').length;$('checkedAt').textContent=state.snapshot.checked_at||'live';$('conversations').innerHTML=cs.length?cs.map(renderConversation).join(''):'<div class="panel muted">No hi ha converses no terminals.</div>';$('alerts').innerHTML=state.alerts.length?state.alerts.map(renderAlert).join(''):'<div class="panel muted">Cap alerta.</div>'}function renderConversation(c){const t=c.current_turn||{};const live=c.live_alerts||[];return `<div class="item"><div class="item-head"><div><div class="name">${esc(c.name)}</div><div class="small muted mono">${esc(c.conversation_id)}</div></div><span class="badge ${esc(c.health)}">${esc(c.health).toUpperCase()}</span></div><div class="kv"><div>Estat<b>${esc(c.status)}</b></div><div>Protocol<b>${esc(c.protocol_version)}</b></div><div>Ronda<b>${esc(c.current_round)} / ${esc(c.max_rounds)}</b></div><div>Torn<b>${esc(t.assigned_agent_id||'—')}</b></div><div>Phase<b>${esc(t.phase||'—')}</b></div><div>Lease<b>${esc(t.lease_until||'—')}</b></div><div>Idle<b>${Math.round(c.idle_seconds||0)} s</b></div><div>Complete pendent<b>${c.completion_pending?'sí':'no'}</b></div></div>${live.map(a=>`<span class="badge ${esc(a.severity)}" style="margin-right:5px">${esc(a.alert_type)}</span>`).join('')}</div>`}function renderAlert(a){return `<div class="item alert-${esc(a.severity)}"><div class="item-head"><div><span class="badge ${esc(a.severity)}">${esc(a.severity)}</span> <b>${esc(a.alert_type)}</b><div class="small muted">${esc(a.message)}</div></div><span class="badge">${esc(a.status)}</span></div><div class="kv"><div>Conversa<b class="mono">${esc(a.conversation_id)}</b></div><div>Primer<b>${esc(a.first_seen_at)}</b></div><div>Últim<b>${esc(a.last_seen_at)}</b></div><div>Ocurrències<b>${esc(a.occurrences)}</b></div></div><div class="row">${a.status==='open'?`<button class="btn" onclick="ack('${esc(a.id)}')">Acknowledge</button>`:''}${a.status!=='resolved'?`<button class="btn" onclick="resolveAlert('${esc(a.id)}')">Resolve</button>`:''}</div></div>`}async function toggleMonitor(){await api('/v1/xerrameca/monitor/system',{method:'PATCH',body:JSON.stringify({enabled:!state.system.enabled})});await refreshAll()}async function saveSettings(){await api('/v1/xerrameca/monitor/system',{method:'PATCH',body:JSON.stringify({poll_interval_seconds:Number($('poll').value),stalled_after_seconds:Number($('stalled').value),near_rounds_threshold:Number($('near').value),loop_window:Number($('loop').value),auto_pause_stalled:$('pauseStalled').checked,auto_pause_loop:$('pauseLoop').checked})});toast('Monitor actualitzat');await refreshAll()}async function tick(){const r=await api('/v1/xerrameca/monitor/tick',{method:'POST'});toast(`Tick: ${r.alerts_seen} alertes, ${r.auto_paused} auto-pausades`);await refreshAll()}async function ack(id){await api(`/v1/xerrameca/monitor/alerts/${id}/acknowledge`,{method:'POST'});await refreshAll()}async function resolveAlert(id){await api(`/v1/xerrameca/monitor/alerts/${id}/resolve`,{method:'POST'});await refreshAll()}if(key)connect();setInterval(()=>{if(key&&!$('app').classList.contains('hidden'))refreshAll().catch(()=>{})},5000);
</script></body></html>'''
